const fs = require('fs');
const basePath = '/Users/teddy/teddy-apps';
const platform = 'facebook';
const system = JSON.parse(fs.readFileSync(basePath + '/automation/content_system.json', 'utf8'));
const historyFiles = {facebook: 'posted_history.json', instagram: 'instagram_history.json', linkedin: 'linkedin_history.json'};
const historyPath = basePath + '/automation/' + historyFiles[platform];
const history = fs.existsSync(historyPath) ? JSON.parse(fs.readFileSync(historyPath, 'utf8')) : [];
if (!Array.isArray(history)) throw new Error('Ugyldig mediehistorik. Stopper for at undgaa gentagelser.');
const imagePattern = /\.(jpg|jpeg|png|webp|avif|heic|bmp|tif|tiff)$/i;
const videoPattern = /\.(mp4|mov|m4v|webm|mkv|avi)$/i;
const allowed = Object.keys(system.posting_schedule.mix);
const candidates = [];

function scan(folder, category) {
  if (!fs.existsSync(folder)) return;
  for (const name of fs.readdirSync(folder).sort()) {
    if (name.startsWith('.')) continue;
    const path = folder + '/' + name;
    const stat = fs.lstatSync(path);
    if (stat.isSymbolicLink()) continue;
    if (stat.isDirectory()) { scan(path, category); continue; }
    if (!stat.isFile() || !stat.size || (!imagePattern.test(name) && !videoPattern.test(name))) continue;
    const mediaId = path.slice(basePath.length + 1);
    const previous = history.filter(h => h.media_id === mediaId || h.media_path === path);
    const lastUsed = previous.reduce((latest, h) => Math.max(latest, Date.parse(h.posted_at) || 0), 0);
    candidates.push({category, media_path: path, media_id: mediaId,
      media_type: videoPattern.test(name) ? 'video' : 'image', lastUsed});
  }
}

for (const category of allowed) {
  const entry = system.categories[category];
  if (!entry || !Array.isArray(entry.posts) || !entry.posts.length) continue;
  if (!/^[a-z-]+$/.test(category) || !entry.image_folder.startsWith('billeder/')) continue;
  if (entry.image_folder.split('/').includes('..')) continue;
  scan(basePath + '/' + entry.image_folder, category);
  scan(basePath + '/videoer/' + category, category);
}
if (!candidates.length) throw new Error('Ingen billeder eller videoer i de aktive indholdsmapper.');

// Every unused asset gets a turn before any asset is reused, across categories.
const oldest = Math.min(...candidates.map(c => c.lastUsed));
let pool = candidates.filter(c => c.lastUsed === oldest);
const otherKind = history[0] && history[0].media_type === 'video' ? 'image' : 'video';
const alternate = pool.filter(c => c.media_type === otherKind);
if (alternate.length) pool = alternate;
const otherCategory = pool.filter(c => !history[0] || c.category !== history[0].category);
if (otherCategory.length) pool = otherCategory;
const weights = pool.map(c => Math.max(1, parseInt(system.posting_schedule.mix[c.category] || '1', 10) || 1));
let needle = Math.random() * weights.reduce((a, b) => a + b, 0);
let selected = pool[pool.length - 1];
for (let i = 0; i < pool.length; i++) {
  needle -= weights[i];
  if (needle < 0) { selected = pool[i]; break; }
}
const allPosts = system.categories[selected.category].posts;
const cutoff = Date.now() - 30 * 86400000;
const freshPosts = allPosts.filter(p => !history.some(h => h.post_id === p.id && Date.parse(h.posted_at) >= cutoff));
const posts = freshPosts.length ? freshPosts : allPosts;
const post = posts[Math.floor(Math.random() * posts.length)];
const separator = String.fromCharCode(10, 10);
return [{json: {...selected, platform, post_id: post.id, headline: post.headline,
  post_text: post.post_text, cta: post.cta, website_url: system.website_url,
  image_path: selected.media_type === 'image' ? selected.media_path : null,
  original_message: [post.headline, post.post_text, post.cta, system.website_url].join(separator)}}];

const fs = require('fs');
const picked = $('Pick Content').item.json;
const response = $json;
const separator = String.fromCharCode(10, 10);
const maxLength = {facebook: 60000, instagram: 2200, linkedin: 3000}[picked.platform];
let message = response && response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content;
if (typeof message !== 'string' || message.trim().length < 50 || message.length > maxLength - 100) {
  message = picked.original_message;
}
message = message.trim();
if (!message.includes(picked.website_url)) message += separator + picked.website_url;
if (message.length > maxLength) throw new Error('Opslagsteksten overskrider platformens graense.');
const executionId = String($execution.id).replace(/[^a-zA-Z0-9_-]/g, '');
if (!executionId) throw new Error('Mangler execution-ID til isoleret medie-payload.');
const runtime = '/Users/teddy/teddy-apps/automation/runtime';
fs.mkdirSync(runtime, {recursive: true, mode: 0o700});
const payloadPath = runtime + '/' + picked.platform + '-' + executionId + '.json';
const payload = {message, media_path: picked.media_path, media_type: picked.media_type,
  media_id: picked.media_id, post_id: picked.post_id, category: picked.category,
  run_id: picked.platform + '-' + executionId};
fs.writeFileSync(payloadPath, JSON.stringify(payload, null, 2), {mode: 0o600});
return [{json: {...picked, final_message: message, payload_path: payloadPath, run_id: payload.run_id}}];

const result = JSON.parse($json.stdout);
if (!result.success) throw new Error('Upload blev ikke bekraeftet.');
return [{json: {...$('Build Message').item.json, ...result}}];

